function line(p,needle,replacement){const s=load(p),a=s.split('\n'),ix=[];a.forEach((v,i)=>{if(v.includes(needle))ix.push(i)});if(ix.length!==1)throw Error('行匹配非一次: '+p+' '+needle+' '+ix.length);a[ix[0]]=typeof replacement==='function'?replacement(a[ix[0]]):replacement;mem.set(p,a.join('\n'))}
